<script setup lang="ts">
import { computed, reactive, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { useMutation, useQuery, useQueryClient } from "@tanstack/vue-query";
import { FileDown, Play, Send } from "lucide-vue-next";
import { api, jsonBody } from "@/api/client";
import { number } from "@/lib/format";
import { useUiStore } from "@/stores/ui";
import PageHeader from "@/components/PageHeader.vue";
import MetricStrip from "@/components/MetricStrip.vue";
import AsyncState from "@/components/AsyncState.vue";
import PriceChart from "@/components/PriceChart.vue";
import CompanyEvidenceSection from "./components/CompanyEvidenceSection.vue";

interface Evidence { id: string; category: string; label: string; value: string; as_of?: string; method?: string; source?: string; page_start?: number; title?: string; retrieval_score?: number }
interface Claim { statement: string; claim_type?: string; confidence?: number; evidence_ids?: string[]; invalidating_conditions?: string[] }
interface Analysis { security: { code: string; name: string }; as_of: string; metrics: Record<string, number | string | null>; series: { dates: string[]; close: number[]; volume: number[] }; evidence: Evidence[]; claims: Claim[]; uncertainties: string[] }
interface Artifact { artifact_id: string; artifact_type: string; schema_version: string; snapshot_hash: string; status: string; payload?: Record<string, unknown> }
interface ResearchRun { run_id?: string; status?: string; as_of?: string; started_at?: string; evidence_count?: number; artifacts?: Artifact[]; snapshot?: ReportSnapshot }
interface ReportSnapshot { security?: { name?: string }; status?: string; executive_summary?: string; coverage?: Record<string, { status?: string; detail?: string; reason?: string }>; claims?: Claim[]; counter_view?: string[]; uncertainties?: string[]; next_checks?: string[] }
interface AssistantAnswer { status: string; answer: string; claims?: Claim[]; limitations?: string[] }
interface FinancialSection { key: string; label: string; status: string; direction: string; summary: string; evidence_ids?: string[] }
interface FinancialTemplate { status: string; period_summary: string; overall_assessment: string; sections: FinancialSection[]; limitations?: string[] }
interface AssistantResult { interaction_id?: string; answer?: AssistantAnswer; template?: FinancialTemplate; evidence?: Evidence[]; result?: AssistantAnswer | FinancialTemplate; interaction_type?: string }
interface HistoryItem { run_id: string; as_of: string; status: string; started_at: string; evidence_count: number }
interface InteractionItem { interaction_id: string; interaction_type: string; question: string; created_at: string; evidence_count: number }
interface FinancialFact { id?: string; fact_id?: string; metric_label: string; current_value: string | number; comparison_value: string | number; normalized_unit?: string; change_pct?: number | null; source?: string; source_page?: number }
interface SecurityMaster { security_code: string; security_name?: string; exchange?: string; board?: string; industry_l1?: string; industry_l2?: string; listing_date?: string; status?: string; source?: string; as_of?: string; attribute_history?: Record<string, unknown> }

const route = useRoute();
const router = useRouter();
const ui = useUiStore();
const client = useQueryClient();
const code = ref(String(route.query.code || "300750.SZ").toUpperCase());
const asOf = ref(String(route.query.as_of || ""));
const tab = ref<"evidence" | "claims" | "assistant" | "report">("evidence");
const assistant = reactive({ question: "", scope: "all" });
const searchQuery = ref("");
const assistantResult = ref<AssistantResult | null>(null);
const report = ref<ResearchRun | null>(null);
watch(() => route.query.code, (value) => { if (value) code.value = String(value).toUpperCase(); });
watch([code, asOf], () => router.replace({ query: { ...route.query, code: code.value, as_of: asOf.value || undefined } }));
const suffix = computed(() => asOf.value ? `?as_of=${asOf.value}` : "");
const analysis = useQuery({ queryKey: computed(() => ["analysis", code.value, asOf.value]), queryFn: () => api<Analysis>(`/api/stocks/${encodeURIComponent(code.value)}/analysis${suffix.value}`), enabled: computed(() => Boolean(code.value)) });
const master = useQuery({ queryKey: computed(() => ["security-master", code.value, asOf.value]), queryFn: () => api<SecurityMaster>(`/api/securities/${encodeURIComponent(code.value)}/master${suffix.value}`), enabled: computed(() => Boolean(code.value)) });
const history = useQuery({ queryKey: computed(() => ["research-runs", code.value]), queryFn: () => api<{ items: HistoryItem[] }>(`/api/stocks/${encodeURIComponent(code.value)}/research-runs?limit=20`) });
const assistantHistory = useQuery({ queryKey: computed(() => ["assistant-history", code.value]), queryFn: () => api<{ items: InteractionItem[] }>(`/api/stocks/${encodeURIComponent(code.value)}/assistant-history?limit=30`) });
const facts = useQuery({ queryKey: computed(() => ["financial-facts", code.value, asOf.value]), queryFn: () => api<{ items: FinancialFact[] }>(`/api/stocks/${encodeURIComponent(code.value)}/financial-facts${suffix.value}`) });
const search = useMutation({ mutationFn: () => api<{ items: Evidence[]; retrieval_method: string }>(`/api/stocks/${encodeURIComponent(code.value)}/evidence-search?q=${encodeURIComponent(searchQuery.value)}${asOf.value ? `&as_of=${asOf.value}` : ""}&limit=20`), onError: (error: Error) => ui.notify(error.message) });
const metrics = computed(() => {
  const values = analysis.data.value?.metrics || {};
  return [
    { label: "20日收益", value: values.return_20d == null ? "—" : `${number(values.return_20d)}%`, note: "动量" },
    { label: "60日年化波动", value: values.volatility_60d == null ? "—" : `${number(values.volatility_60d)}%`, note: "风险" },
    { label: "250日最大回撤", value: values.max_drawdown_250d == null ? "—" : `${number(values.max_drawdown_250d)}%`, note: "峰值至谷值" },
    { label: "52周位置", value: values.range_position_52w == null ? "—" : `${number(values.range_position_52w)}%`, note: "区间百分位" },
    { label: "20日量比", value: values.volume_ratio_20d == null ? "—" : `${number(values.volume_ratio_20d)}x`, note: "当日 / 均值" },
    { label: "趋势结构", value: values.trend || "—", note: "20 / 60日" },
  ];
});
const research = useMutation({ mutationFn: () => api<ResearchRun>("/api/research-runs", { method: "POST", ...jsonBody({ code: code.value, as_of: asOf.value || null, depth: "quick", factor_snapshot_id: route.query.snapshot_id || null }) }), onSuccess: async (data) => { report.value = withSnapshot(data); tab.value = "report"; ui.notify("公司研究已完成"); await client.invalidateQueries({ queryKey: ["research-runs", code.value] }); }, onError: notifyError });
const ask = useMutation({ mutationFn: () => api<AssistantResult>("/api/document-assistant", { method: "POST", ...jsonBody({ code: code.value, question: assistant.question, as_of: asOf.value || null, scope: assistant.scope }) }), onSuccess: async (data) => { assistantResult.value = data; ui.notify("文档问答已保存到研究历史"); await client.invalidateQueries({ queryKey: ["assistant-history", code.value] }); }, onError: notifyError });
const financial = useMutation({ mutationFn: () => api<AssistantResult>("/api/financial-change-template", { method: "POST", ...jsonBody({ code: code.value, as_of: asOf.value || null }) }), onSuccess: async (data) => { assistantResult.value = data; ui.notify("财务变化模板已生成"); await Promise.all([client.invalidateQueries({ queryKey: ["assistant-history", code.value] }), client.invalidateQueries({ queryKey: ["financial-facts", code.value] })]); }, onError: notifyError });
const refreshFacts = useMutation({ mutationFn: () => api(`/api/stocks/${encodeURIComponent(code.value)}/financial-facts/refresh${suffix.value}`, { method: "POST" }), onSuccess: async () => { ui.notify("财务事实已重新提取"); await client.invalidateQueries({ queryKey: ["financial-facts", code.value] }); }, onError: notifyError });
const sync = useMutation({ mutationFn: () => api(`/api/stocks/${encodeURIComponent(code.value)}/announcements/sync?as_of=${encodeURIComponent(asOf.value || analysis.data.value?.as_of || "")}&lookback_days=365&download_limit=5&document_scope=all`, { method: "POST" }), onSuccess: () => ui.notify("公告同步完成"), onError: notifyError });
function notifyError(error: Error) { ui.notify(error.message); }
function withSnapshot(data: ResearchRun) { const artifact = data.artifacts?.find((item) => item.artifact_type === "company_snapshot"); return { ...data, snapshot: artifact?.payload as ReportSnapshot | undefined }; }
async function openRun(id: string) { try { report.value = withSnapshot(await api<ResearchRun>(`/api/research-runs/${encodeURIComponent(id)}`)); tab.value = "report"; } catch (error) { notifyError(error as Error); } }
async function openInteraction(id: string) { try { const data = await api<AssistantResult>(`/api/research-interactions/${encodeURIComponent(id)}`); const result = data.result; assistantResult.value = { ...data, [data.interaction_type === "financial_change_template" ? "template" : "answer"]: result }; tab.value = "assistant"; } catch (error) { notifyError(error as Error); } }
function sourceHref(item: Evidence | FinancialFact) { return item.source || ""; }
</script>

<template>
  <PageHeader eyebrow="COMPANY RESEARCH" :title="analysis.data.value?.security?.name||'公司分析'" :description="`${analysis.data.value?.security?.code||code} · 截至 ${analysis.data.value?.as_of||'—'} · 所有结论绑定证据与时间边界`">
    <label for="company-code">证券代码<input id="company-code" v-model="code" /></label><label for="company-as-of">研究截止日<input id="company-as-of" v-model="asOf" type="date" /></label>
    <button class="button secondary" :disabled="sync.isPending.value" @click="sync.mutate()"><FileDown :size="14" />同步公告</button><button class="button" :disabled="research.isPending.value" @click="research.mutate()"><Play :size="14" />生成研究</button>
  </PageHeader>
  <AsyncState :loading="analysis.isPending.value" :error="analysis.error.value" @retry="analysis.refetch()">
    <MetricStrip :items="metrics" />
    <section class="content-band white"><PriceChart :dates="analysis.data.value?.series?.dates||[]" :close="analysis.data.value?.series?.close||[]" :volume="analysis.data.value?.series?.volume||[]" /><div class="panel-grid" style="margin-top:18px"><article class="panel"><h3>上市与交易</h3><p>{{ master.data.value?.listing_date||'未知上市日' }} · {{ master.data.value?.exchange }} · {{ master.data.value?.board||'未知板块' }}</p></article><article class="panel"><h3>行业</h3><p>{{ master.data.value?.industry_l1||'未知一级行业' }} · {{ master.data.value?.industry_l2||'未知二级行业' }}</p></article><article class="panel"><h3>主数据合同</h3><p>{{ master.data.value?.source }} · 截至 {{ master.data.value?.as_of||analysis.data.value?.as_of }}</p></article></div></section>
    <nav class="tabs" aria-label="公司研究视图"><button :class="{active:tab==='evidence'}" @click="tab='evidence'">证据链 {{ analysis.data.value?.evidence?.length||0 }}</button><button :class="{active:tab==='claims'}" @click="tab='claims'">研究论点 {{ analysis.data.value?.claims?.length||0 }}</button><button :class="{active:tab==='assistant'}" @click="tab='assistant'">文档助手</button><button :class="{active:tab==='report'}" @click="tab='report'">AI 报告</button></nav>
    <CompanyEvidenceSection v-if="tab==='evidence'" v-model="searchQuery" :evidence="analysis.data.value?.evidence || []" :uncertainties="analysis.data.value?.uncertainties || []" :results="search.data.value" :searching="search.isPending.value" @search="search.mutate()" />
    <section v-else-if="tab==='claims'" class="content-band white"><div class="list"><article v-for="item in analysis.data.value?.claims||[]" :key="item.statement" class="list-item"><header><span class="status">{{ item.claim_type==='fact'?'事实':'推断' }}</span><span>{{ Math.round((item.confidence||0)*100) }}%</span></header><p>{{ item.statement }}</p><footer><span>证据 {{ item.evidence_ids?.join(' · ') }}</span><span>证伪 {{ item.invalidating_conditions?.join('；')||'尚未定义' }}</span></footer></article></div></section>
    <section v-else-if="tab==='assistant'" class="two-column"><main class="content-band white"><form class="form-grid" @submit.prevent="ask.mutate()"><label for="assistant-scope">文档范围<select id="assistant-scope" v-model="assistant.scope"><option value="all">全部公告</option><option value="financial_reports">财报与业绩公告</option><option value="announcements">一般公告</option></select></label><label class="wide" for="assistant-question">研究问题<textarea id="assistant-question" v-model="assistant.question" required minlength="2" rows="4" /></label><button class="button" :disabled="ask.isPending.value"><Send :size="14" />提交问题</button><button type="button" class="button secondary" :disabled="financial.isPending.value" @click="financial.mutate()">生成财务变化模板</button><button type="button" class="button secondary" :disabled="refreshFacts.isPending.value" @click="refreshFacts.mutate()">重新提取财务事实</button></form><article v-if="assistantResult?.answer" class="panel" style="margin-top:20px"><span class="status">{{ assistantResult.answer.status }}</span><h3 style="margin-top:12px">{{ assistantResult.answer.answer }}</h3><div class="list"><article v-for="claim in assistantResult.answer.claims||[]" :key="claim.statement" class="list-item"><p>{{ claim.statement }}</p><footer>{{ claim.evidence_ids?.join(' · ') }}</footer></article></div></article><article v-if="assistantResult?.template" class="panel" style="margin-top:20px"><span class="status">{{ assistantResult.template.status }}</span><h3 style="margin-top:12px">{{ assistantResult.template.period_summary }}</h3><p>{{ assistantResult.template.overall_assessment }}</p><div class="list" style="margin-top:12px"><article v-for="section in assistantResult.template.sections||[]" :key="section.key" class="list-item"><header><h3>{{ section.label }}</h3><span :class="['status',section.status==='supported'?'':'warn']">{{ section.direction }}</span></header><p>{{ section.summary }}</p></article></div></article><div class="section-heading" style="margin-top:20px"><div><span>FINANCIAL FACTS</span><b>程序化财务事实</b></div><small>{{ facts.data.value?.items?.length||0 }}</small></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>指标</th><th>本期</th><th>比较期</th><th>变化</th><th>来源</th></tr></thead><tbody><tr v-for="fact in facts.data.value?.items||[]" :key="fact.id||fact.fact_id"><td>{{ fact.metric_label }}</td><td>{{ fact.current_value }} {{ fact.normalized_unit }}</td><td>{{ fact.comparison_value }}</td><td>{{ fact.change_pct==null?'—':`${number(fact.change_pct)}%` }}</td><td><a v-if="sourceHref(fact)" class="source-link" :href="sourceHref(fact)" target="_blank" rel="noopener">p.{{ fact.source_page }}</a><span v-else>p.{{ fact.source_page||'—' }}</span></td></tr></tbody></table></div></main><aside class="content-band"><div class="section-heading"><div><span>INTERACTIONS</span><b>助手历史</b></div><small>{{ assistantHistory.data.value?.items?.length||0 }}</small></div><div class="list"><button v-for="item in assistantHistory.data.value?.items||[]" :key="item.interaction_id" class="list-item" style="text-align:left" @click="openInteraction(item.interaction_id)"><h3>{{ item.interaction_type==='financial_change_template'?'财务变化模板':'文档问答' }}</h3><p>{{ item.question }}</p><footer>{{ item.created_at }} · {{ item.evidence_count }} 条证据</footer></button></div></aside></section>
    <section v-else class="two-column"><main class="content-band white"><AsyncState :empty="!report" empty-text="尚未运行或选择公司研究"><div class="section-heading"><div><span>RESEARCH RUN</span><b>{{ report?.snapshot?.security?.name||analysis.data.value?.security?.name }} 公司研究快照</b></div><span class="status">{{ report?.status||report?.snapshot?.status }}</span></div><p>{{ report?.snapshot?.executive_summary }}</p><div class="panel-grid" style="margin-top:18px"><article class="panel" v-for="(value,key) in report?.snapshot?.coverage||{}" :key="key"><h3>{{ key }}</h3><p>{{ value.status }} · {{ value.detail||value.reason }}</p></article></div><div class="section-heading" style="margin-top:24px"><div><span>FROZEN ARTIFACTS</span><b>研究产物台账</b></div></div><div class="list"><article v-for="artifact in report?.artifacts||[]" :key="artifact.artifact_id" class="list-item"><header><h3>{{ artifact.artifact_type }}</h3><span :class="['status',artifact.status==='completed'?'':'warn']">{{ artifact.status }}</span></header><p>{{ artifact.schema_version }}</p><footer><code>{{ artifact.snapshot_hash }}</code></footer></article></div><div class="section-heading" style="margin-top:24px"><div><span>CLAIMS & COUNTER VIEW</span><b>结论与反方证据</b></div></div><div class="list"><article v-for="claim in report?.snapshot?.claims||[]" :key="claim.statement" class="list-item"><p>{{ claim.statement }}</p><footer><span>置信度 {{ Math.round((claim.confidence||0)*100) }}%</span><span>证据 {{ claim.evidence_ids?.join(' · ') }}</span></footer></article><article v-for="item in report?.snapshot?.counter_view||[]" :key="item" class="list-item"><p>{{ item }}</p></article></div><div class="section-heading" style="margin-top:24px"><div><span>NEXT CHECKS</span><b>下一步核验</b></div></div><div class="list"><article v-for="item in report?.snapshot?.next_checks||[]" :key="item" class="list-item"><p>{{ item }}</p></article></div></AsyncState></main><aside class="content-band"><div class="section-heading"><div><span>RUN HISTORY</span><b>研究历史</b></div><small>{{ history.data.value?.items?.length||0 }}</small></div><div class="list"><button v-for="item in history.data.value?.items||[]" :key="item.run_id" class="list-item" style="text-align:left" @click="openRun(item.run_id)"><header><h3>{{ item.as_of }} 公司研究</h3><span class="status">{{ item.status }}</span></header><p>{{ item.started_at }} · {{ item.evidence_count }} 条证据</p></button></div></aside></section>
  </AsyncState>
</template>
